(1, 'https://webranker.in', 'founder@startup.com', '+919876543210', 68, 96, '{\"cls\": \"0.04\", \"fcp\": \"7.0 s\", \"lcp\": \"13.0 s\", \"tbt\": \"480 ms\", \"ttfb\": \"5007 ms\", \"source\": \"live_heuristic_diagnostic\", \"seo_score\": 96, \"cwv_status\": \"NEEDS IMPROVEMENT\", \"speed_index\": \"9.0 s\", \"opportunities\": [\"Server response time (TTFB) is higher than recommended 200 ms\", \"Defer non-critical third-party JavaScript & unminified stylesheets\", \"Serve hero banners and responsive images in modern WebP/AVIF formats\"], \"performance_score\": 68}', '{\"speed_fixes\": [\"Implement edge caching via a global CDN (e.g., Cloudflare or Vercel Edge) to reduce TTFB from 5007ms to under 200ms by serving static assets and cached HTML from locations closest to the user.\", \"Defer all non-critical third-party JavaScript using the \'defer\' attribute or dynamic import patterns, and inline critical CSS while purging unused styles from the main bundle to reduce TBT from 480ms to under 200ms.\", \"Convert all hero banners and responsive images to AVIF or WebP formats with appropriate srcset attributes, and implement lazy loading for below-the-fold images to reduce LCP from 13.0s to under 2.5s.\"], \"schema_fixes\": [\"Implement Organization JSON-LD schema with logo, sameAs links to social profiles, and address details to enhance brand entity recognition and local relevance.\", \"Add BreadcrumbList schema to all non-homepage URLs and WebSite schema with potentialAction for site search to improve navigation visibility and SERP presentation.\", \"Ensure strict canonical URL implementation to prevent duplicate content issues, and optimize OpenGraph tags and semantic HTML5 hierarchy (single H1, proper heading structure) for better crawlability and social sharing.\"], \"executive_summary\": \"The site\'s primary organic ranking barrier is a critical 5-second TTFB caused by slow server response, which severely degrades LCP to 13.0s and undermines the otherwise strong 96/100 SEO score. Immediate infrastructure optimization is required to reduce server latency and render-blocking resources to unlock the full potential of the existing high-quality content.\", \"keyword_opportunities\": [\"Target high-intent commercial keywords such as \'AI SEO tools for Indian startups\' and \'technical SEO audit services India\' to capture bottom-funnel traffic with clear purchase intent.\", \"Establish topical authority by creating a dedicated \'Technical SEO\' pillar page with internal link silos connecting to specific sub-topics like \'Core Web Vitals optimization\' and \'Server-side rendering best practices.\'\", \"Displace competitors in SERPs for \'best SEO agencies in India\' by optimizing for featured snippets and AI Overviews with concise, data-driven answers and structured comparison tables.\"]}', '127.0.0.1', 'India', 'completed', NULL, '2026-09-25 04:31:13', '2026-09-25 04:31:13'),
(2, 'https://stripe.com', 'tech@stripe.com', '+14155552671', 63, 96, '{\"cls\": \"0.04\", \"fcp\": \"6.9 s\", \"lcp\": \"12.8 s\", \"tbt\": \"480 ms\", \"ttfb\": \"4916 ms\", \"source\": \"live_heuristic_diagnostic\", \"seo_score\": 96, \"cwv_status\": \"NEEDS IMPROVEMENT\", \"speed_index\": \"8.8 s\", \"opportunities\": [\"Server response time (TTFB) is higher than recommended 200 ms\", \"Defer non-critical third-party JavaScript & unminified stylesheets\", \"Serve hero banners and responsive images in modern WebP/AVIF formats\"], \"performance_score\": 63}', '{\"speed_fixes\": [\"Implement edge caching and a global CDN (e.g., Cloudflare or Vercel Edge) to reduce TTFB from 4916ms to <200ms by serving static assets and API responses from the nearest geographic node.\", \"Defer non-critical third-party JavaScript (analytics, chat widgets) using `defer` or `async` attributes and implement dynamic import for heavy modules to reduce TBT from 480ms to <200ms.\", \"Convert all hero banners and responsive images to AVIF/WebP formats with `srcset` and `sizes` attributes, and preload the LCP image to reduce LCP from 12.8s to <2.5s.\"], \"schema_fixes\": [\"Implement Organization JSON-LD schema with `logo`, `sameAs` (social profiles), and `contactPoint` to enhance brand entity understanding and rich result eligibility.\", \"Add BreadcrumbList schema to all subpages and WebSite schema with `SearchAction` to enable sitelinks search box in SERPs for improved CTR and navigation.\", \"Ensure canonical tags are correctly implemented to prevent duplicate content, optimize OpenGraph tags for social sharing, and enforce semantic HTML5 hierarchy (H1-H6) to improve crawlability and accessibility.\"], \"executive_summary\": \"Stripe.com\'s elite SEO score (96/100) is severely undermined by a critical performance bottleneck (63/100), primarily driven by a 4.9s TTFB and 12.8s LCP that risk organic visibility despite strong content authority. Immediate infrastructure optimization is required to reduce server latency and render-blocking resources to prevent user drop-off and improve Core Web Vitals rankings.\", \"keyword_opportunities\": [\"Target high-intent long-tail keywords like \'payment gateway api documentation\', \'stripe vs paypal integration guide\', and \'how to accept crypto payments with stripe\' to capture developers and fintech integrators.\", \"Build a topical authority silo around \'Payment Infrastructure\' with internal links from blog posts to core product pages (e.g., Payment Links, Billing, Connect) to reinforce semantic relevance for \'payment processing solutions\'.\", \"Displace competitors in SERPs for \'best payment gateway for saas\' and \'ecommerce payment integration\' by creating comprehensive comparison guides and case studies that directly address user pain points with data-driven results.\"]}', '127.0.0.1', 'India', 'completed', NULL, '2026-09-25 04:37:58', '2026-09-25 04:37:58'),
(3, 'https://ai.dotsquares.com', 'devpankaj@yopmail.com', '9876543210', 73, 55, '{\"cls\": \"0.18\", \"fcp\": \"7.2 s\", \"lcp\": \"13.4 s\", \"tbt\": \"480 ms\", \"ttfb\": \"5142 ms\", \"source\": \"live_heuristic_diagnostic\", \"seo_score\": 55, \"cwv_status\": \"NEEDS IMPROVEMENT\", \"speed_index\": \"9.3 s\", \"opportunities\": [\"Missing Organization & WebSite JSON-LD Schema structured data\", \"Missing self-referencing canonical tag to prevent duplicate indexation\", \"Meta description is missing or suboptimal for Google SERP CTR\", \"Server response time (TTFB) is higher than recommended 200 ms\"], \"performance_score\": 73}', '{\"speed_fixes\": [\"Implement edge caching or a robust CDN (e.g., Vercel/Cloudflare) with aggressive static asset pre-rendering to reduce TTFB from 5142ms to under 200ms.\", \"Refactor JavaScript loading by implementing dynamic imports for non-critical components and deferring third-party scripts to reduce TBT from 480ms to under 200ms.\", \"Optimize Largest Contentful Paint (LCP) by serving the hero image in AVIF/WebP format with explicit width/height attributes to prevent CLS and prioritizing fetch priority.\"], \"schema_fixes\": [\"Implement Organization JSON-LD schema including name, logo, sameAs social profiles, and contactPoint to establish entity trust and rich result eligibility.\", \"Add WebSite and BreadcrumbList schemas to enhance site navigation visibility in SERPs and improve click-through rates via structured breadcrumbs.\", \"Add self-referencing canonical tags to all indexable pages, optimize meta descriptions for CTR, and enforce semantic HTML5 hierarchy (single H1, proper H2-H6 nesting) for crawl efficiency.\"], \"executive_summary\": \"The site suffers from severe server-side latency (5.1s TTFB) and heavy client-side blocking, causing an LCP of 13.4s that disqualifies it from top rankings due to poor Core Web Vitals. Additionally, the absence of critical structured data and canonical tags prevents Google from correctly interpreting entity relationships and consolidating page authority.\", \"keyword_opportunities\": [\"Target high-intent commercial keywords such as \'AI development agency\', \'custom AI solutions\', and \'enterprise AI consulting\' to capture bottom-funnel traffic.\", \"Establish topical authority by creating a content silo around \'AI Implementation Roadmaps\' and \'Machine Learning Case Studies\' with strong internal linking to the homepage.\", \"Displace competitors in SERPs for \'AI automation tools\' and \'predictive analytics services\' by targeting long-tail variations with higher specificity and lower competition.\"]}', '127.0.0.1', 'India', 'completed', NULL, '2026-09-25 04:41:54', '2026-09-25 04:41:54');

